window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b2058d12484fbd86"]={"versions": [{"id": "FIG-b2058d12484fbd86", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm zur Darstellung einer unzulässigen Port-Verbindung im Kontext des AUTOSAR-Software-Component-Templates (Classic Platform / VFB-Modellierung). Die Abbildung veranschaulicht eine fehlerhafte semantische Kopplung zwischen einer Anwendungs-Softwarekomponente und einer NVRAM-Block-Softwarekomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Software-Komponententypen:</p>\n<ul class=\"fig-list\"><li><code>ApplicationSwComponentType</code> „A“ mit einer <code>RunnableEntity</code> und einem PR-Port (gekennzeichnet durch ein Quadrat mit Raute). Innerhalb der Komponente greift die <code>RunnableEntity</code> sowohl über <code>Write Access</code> als auch über <code>Read Access</code> (jeweils gestrichelte Pfeile) auf den Port zu.\n</li><li><code>NvBlockSwComponentType</code> „B“ mit einem <code>ramBlock</code>, einem <code>Mapping</code>-Element und einem Eingangs-/Empfänger-Port (Quadrat mit nach rechts gerichtetem Dreieck). Das <code>Mapping</code> referenziert den <code>ramBlock</code> (durchgehender Pfeil nach unten) und den Port (gestrichelter Pfeil nach rechts).\n</li><li>Zwischen den Ports beider Komponenten verläuft eine mit <code>Connector</code> beschriftete Verbindungslinie. Ein trauriges Smiley-Symbol markiert die Ungültigkeit der Verbindung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturbeispiel ohne dynamische Zeit- oder Sequenzabläufe. Dargestellt sind die potenziellen Zugriffe: Die <code>RunnableEntity</code> in Komponente A fordert sowohl Lese- als auch Schreibzugriff auf ihren Port an. In Komponente B ist das <code>Mapping</code> auf den <code>ramBlock</code> und den Port gerichtet. Über den <code>Connector</code> sind die Ports miteinander verschaltet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert ein Negativbeispiel (invalid connection). Es verdeutlicht ein unzulässiges Modellierungsmuster: Die Bereitstellung von kombinierten Schreib- und Lesezugriffen (<code>Write Access</code>, <code>Read Access</code>) über denselben Port einer <code>ApplicationSwComponentType</code> ist inkompatibel zu der gezeigten Port-/Mapping-Konfiguration des <code>NvBlockSwComponentType</code>. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass solche Port-Kombinationen bzw. Zugriffsarten nicht über einen Konnektor verbunden werden.</p>"}, {"id": "FIG-68b29e9b18259a32", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm zur Darstellung einer unzulässigen Port-Verbindung im Kontext des AUTOSAR-Software-Component-Templates (Classic Platform / VFB-Modellierung). Die Abbildung veranschaulicht eine fehlerhafte semantische Kopplung zwischen einer Anwendungs-Softwarekomponente und einer NVRAM-Block-Softwarekomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Software-Komponententypen:</p>\n<ul class=\"fig-list\"><li><code>ApplicationSwComponentType</code> „A“ mit einer <code>RunnableEntity</code> und einem PR-Port (gekennzeichnet durch ein Quadrat mit Raute). Innerhalb der Komponente greift die <code>RunnableEntity</code> sowohl über <code>Write Access</code> als auch über <code>Read Access</code> (jeweils gestrichelte Pfeile) auf den Port zu.\n</li><li><code>NvBlockSwComponentType</code> „B“ mit einem <code>ramBlock</code>, einem <code>Mapping</code>-Element und einem Eingangs-/Empfänger-Port (Quadrat mit nach rechts gerichtetem Dreieck). Das <code>Mapping</code> referenziert den <code>ramBlock</code> (durchgehender Pfeil nach unten) und den Port (gestrichelter Pfeil nach rechts).\n</li><li>Zwischen den Ports beider Komponenten verläuft eine mit <code>Connector</code> beschriftete Verbindungslinie. Ein trauriges Smiley-Symbol markiert die Ungültigkeit der Verbindung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturbeispiel ohne dynamische Zeit- oder Sequenzabläufe. Dargestellt sind die potenziellen Zugriffe: Die <code>RunnableEntity</code> in Komponente A fordert sowohl Lese- als auch Schreibzugriff auf ihren Port an. In Komponente B ist das <code>Mapping</code> auf den <code>ramBlock</code> und den Port gerichtet. Über den <code>Connector</code> sind die Ports miteinander verschaltet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert ein Negativbeispiel (invalid connection). Es verdeutlicht ein unzulässiges Modellierungsmuster: Die Bereitstellung von kombinierten Schreib- und Lesezugriffen (<code>Write Access</code>, <code>Read Access</code>) über denselben Port einer <code>ApplicationSwComponentType</code> ist inkompatibel zu der gezeigten Port-/Mapping-Konfiguration des <code>NvBlockSwComponentType</code>. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass solche Port-Kombinationen bzw. Zugriffsarten nicht über einen Konnektor verbunden werden.</p>"}, {"id": "FIG-861803424f28ef96", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm zur Darstellung einer unzulässigen Port-Verbindung im Kontext des AUTOSAR-Software-Component-Templates (Classic Platform / VFB-Modellierung). Die Abbildung veranschaulicht eine fehlerhafte semantische Kopplung zwischen einer Anwendungs-Softwarekomponente und einer NVRAM-Block-Softwarekomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Software-Komponententypen:</p>\n<ul class=\"fig-list\"><li><code>ApplicationSwComponentType</code> „A“ mit einer <code>RunnableEntity</code> und einem PR-Port (gekennzeichnet durch ein Quadrat mit Raute). Innerhalb der Komponente greift die <code>RunnableEntity</code> sowohl über <code>Write Access</code> als auch über <code>Read Access</code> (jeweils gestrichelte Pfeile) auf den Port zu.\n</li><li><code>NvBlockSwComponentType</code> „B“ mit einem <code>ramBlock</code>, einem <code>Mapping</code>-Element und einem Eingangs-/Empfänger-Port (Quadrat mit nach rechts gerichtetem Dreieck). Das <code>Mapping</code> referenziert den <code>ramBlock</code> (durchgehender Pfeil nach unten) und den Port (gestrichelter Pfeil nach rechts).\n</li><li>Zwischen den Ports beider Komponenten verläuft eine mit <code>Connector</code> beschriftete Verbindungslinie. Ein trauriges Smiley-Symbol markiert die Ungültigkeit der Verbindung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturbeispiel ohne dynamische Zeit- oder Sequenzabläufe. Dargestellt sind die potenziellen Zugriffe: Die <code>RunnableEntity</code> in Komponente A fordert sowohl Lese- als auch Schreibzugriff auf ihren Port an. In Komponente B ist das <code>Mapping</code> auf den <code>ramBlock</code> und den Port gerichtet. Über den <code>Connector</code> sind die Ports miteinander verschaltet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert ein Negativbeispiel (invalid connection). Es verdeutlicht ein unzulässiges Modellierungsmuster: Die Bereitstellung von kombinierten Schreib- und Lesezugriffen (<code>Write Access</code>, <code>Read Access</code>) über denselben Port einer <code>ApplicationSwComponentType</code> ist inkompatibel zu der gezeigten Port-/Mapping-Konfiguration des <code>NvBlockSwComponentType</code>. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass solche Port-Kombinationen bzw. Zugriffsarten nicht über einen Konnektor verbunden werden.</p>"}, {"id": "FIG-f404b76051a4687e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm zur Darstellung einer unzulässigen Port-Verbindung im Kontext des AUTOSAR-Software-Component-Templates (Classic Platform / VFB-Modellierung). Die Abbildung veranschaulicht eine fehlerhafte semantische Kopplung zwischen einer Anwendungs-Softwarekomponente und einer NVRAM-Block-Softwarekomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei nebeneinander angeordnete Software-Komponententypen:</p>\n<ul class=\"fig-list\"><li><code>ApplicationSwComponentType</code> „A“ (links) mit einer <code>RunnableEntity</code> und einem PR-Port (Quadrat mit Raute am rechten Rand). Innerhalb der Komponente greift die <code>RunnableEntity</code> über <code>Write Access</code> und <code>Read Access</code> (gestrichelte Pfeile) auf diesen Port zu.\n</li><li><code>NvBlockSwComponentType</code> „B“ (rechts) mit einem <code>ramBlock</code>, einem <code>Mapping</code>-Element und einem Port (Quadrat mit nach links gerichtetem Dreieck am linken Rand). Das <code>Mapping</code> zeigt mit einem durchgehenden Pfeil nach unten auf <code>ramBlock</code> und mit einem gestrichelten Pfeil nach links auf den Port.\n</li><li>Eine direkte Verbindungslinie (<code>Connector</code>) verbindet beide Ports. Ein trauriges Smiley-Symbol unterhalb des Connectors signalisiert die Unzulässigkeit der Verbindung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturbeispiel ohne dynamische Zeit- oder Sequenzabläufe. Dargestellt sind die potenziellen Zugriffe: Die <code>RunnableEntity</code> in Komponente A fordert sowohl Lese- als auch Schreibzugriff auf ihren Port an. In Komponente B ist das <code>Mapping</code> auf den <code>ramBlock</code> und den Port gerichtet. Über den <code>Connector</code> sind die Ports miteinander verschaltet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert ein Negativbeispiel (invalid connection). Es verdeutlicht ein unzulässiges Modellierungsmuster: Die Bereitstellung von kombinierten Schreib- und Lesezugriffen (<code>Write Access</code>, <code>Read Access</code>) über denselben Port einer <code>ApplicationSwComponentType</code> ist inkompatibel zu der gezeigten Port-/Mapping-Konfiguration des <code>NvBlockSwComponentType</code>. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass solche Port-Kombinationen bzw. Zugriffsarten nicht über einen Konnektor verbunden werden.</p>"}], "trans": [{"from": "FIG-b2058d12484fbd86", "to": "FIG-68b29e9b18259a32", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-68b29e9b18259a32", "to": "FIG-861803424f28ef96", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-861803424f28ef96", "to": "FIG-f404b76051a4687e", "fr": "R20-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Gesamtdiagramm: Anordnung der Komponenten von vertikal (übereinander) auf horizontal (nebeneinander) umgestellt.\n</li><li>Verbindungslinie (<code>Connector</code>): Verlauf von abgewinkelt vertikal zu einer direkten diagonalen Verbindung angepasst.\n</li><li>Portsymbol an Komponente B: Dreiecks-Richtungssymbol von nach rechts zeigend auf nach links zeigend gedreht, passend zur Ausrichtung nach links zu Komponente A.\n</li></ul>"}]};
